  "signal_basis": {
    "component_id": "C056_SIGNAL",
    "value": "Repeated, evidence-based classifications of revision tail rates shrink the candidate transition interval, localizing an associated revision boundary without establishing a sole cause.",
    "scope": "Valid endpoints, comparable trials and a persistent single transition; classifications account for sampling uncertainty and repeated testing, and an unresolved interval remains when further classification is infeasible.",
